TLM.f("Sancti/11-25",{"officium":"S. Catharinæ Virginis et Martyris","rule":["vide C6;","Gloria"],"ruleInherited":["Gloria"],"fallback":"Commune/C6","from":{"Introitus":"Commune/C6","Lectio":"Commune/C6","Graduale":"Commune/C6","GradualeP":"Commune/C6","Tractus":"Commune/C6","Evangelium":"Commune/C6","Offertorium":"Commune/C6","Communio":"Commune/C6"},"sections":{"Introitus":[{"k":"ref","la":"Ps 118:46-47"},{"k":"text","la":"Loquébar de testimóniis tuis in conspéctu regum, et non confundébar: et meditábar in mandátis tuis, quæ diléxi nimis. (Allelúja, allelúja.)"},{"k":"ref","la":"Ps 118:1"},{"k":"text","la":"Beáti immaculáti in via: qui ámbulant in lege Dómini."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Loquébar de testimóniis tuis in conspéctu regum, et non confundébar: et meditábar in mandátis tuis, quæ diléxi nimis. (Allelúja, allelúja.)"}],"Oratio":[{"k":"text","la":"Deus, qui dedísti legem Móysi in summitáte montis Sínai, et in eódem loco per sanctos Angelos tuos corpus beátæ Catharínæ Vírginis et Mártyris tuæ mirabíliter collocásti: præsta, quǽsumus; ut, ejus méritis et intercessióne, ad montem, qui Christus est, perveníre valeámus."},{"k":"macro","name":"Qui tecum"}],"Lectio":[{"k":"text","la":"Léctio libri Sapiéntiæ"},{"k":"ref","la":"Eccli 51:1-8; 51:12"},{"k":"text","la":"Confitébor tibi, Dómine, Rex, et collaudábo te Deum, Salvatórem meum. Confitébor nómini tuo: quóniam adjútor et protéctor factus es mihi, et liberásti corpus meum a perditióne, a láqueo línguæ iníquæ et a lábiis operántium mendácium, et in conspéctu astántium factus es mihi adjutor. Et liberasti me secúndum multitúdinem misericórdiæ nóminis tui a rugiéntibus, præparátis ad escam, de mánibus quæréntium ánimam meam, et de portis tribulatiónum, quæ circumdedérunt me: a pressúra flammæ, quæ circúmdedit me, et in médio ignis non sum æstuáta: de altitúdine ventris inferi, et a lingua coinquináta, et a verbo mendácii, a rege iníquo, et a lingua injústa: laudábit usque ad mortem ánima mea Dóminum: quóniam éruis sustinéntes te, et líberas eos de mánibus géntium, Dómine, Deus noster."}],"Graduale":[{"k":"ref","la":"Ps 44:8"},{"k":"text","la":"Dilexísti justítiam, et odísti iniquitátem."},{"k":"text","la":"Proptérea unxit te Deus, Deus tuus, óleo lætítiæ.","mark":"V"},{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 44:15; 44:16"},{"k":"text","la":"Adducéntur Regi Vírgines post eam: próximæ ejus afferéntur tibi in lætítia. Allelúja."}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 44:15; 44:16"},{"k":"text","la":"Adducéntur Regi Vírgines post eam: próximæ ejus afferéntur tibi in lætítia. Allelúja."},{"k":"ref","la":"Ps 44:5"},{"k":"text","la":"Spécie tua et pulchritúdine tua inténde, próspere procéde et regna. Allelúja."}],"Tractus":[{"k":"ref","la":"Ps 44:8"},{"k":"text","la":"Dilexísti justítiam, et odísti iniquitátem."},{"k":"text","la":"Proptérea unxit te Deus, Deus tuus, óleo lætítiæ.","mark":"V"},{"k":"text","la":"Veni, Sponsa Christi, áccipe corónam, quam tibi Dóminus præparávit in ætérnum: pro cujus amóre sánguinem tuum fudísti."},{"k":"ref","la":"Ps 44:8; 44:5"},{"k":"text","la":"Dilexísti justítiam, et odísti iniquitátem: proptérea unxit te Deus, Deus tuus, óleo lætítiæ præ consórtibus tuis."},{"k":"text","la":"Spécie tua et pulchritúdine tua inténde, próspere procéde et regna.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 25:1-13"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis parábolam hanc: Símile erit regnum coelórum decem virgínibus: quæ, accipiéntes lámpades suas, exiérunt óbviam sponso et sponsæ. Quinque autem ex eis erant fátuæ, et quinque prudéntes: sed quinque fátuæ, accéptis lampádibus, non sumpsérunt óleum secum: prudéntes vero accepérunt óleum in vasis suis cum lampádibus. Moram autem faciénte sponso, dormitavérunt omnes et dormiérunt. Média autem nocte clamor factus est: Ecce, sponsus venit, exíte óbviam ei. Tunc surrexérunt omnes vírgines illae, et ornavérunt lámpades suas. Fátuæ autem sapiéntibus dixérunt: Date nobis de óleo vestro: quia lámpades nostræ exstinguúntur. Respondérunt prudéntes, dicéntes: Ne forte non suffíciat nobis et vobis, ite pótius ad vendéntes, et émite vobis. Dum autem irent émere, venit sponsus: et quæ parátæ erant, intravérunt cum eo ad núptias, et clausa est jánua. Novíssime vero véniunt et réliquæ vírgines, dicéntes: Dómine, Dómine, áperi nobis. At ille respóndens, ait: Amen, dico vobis, néscio vos. Vigiláte ítaque, quia nescítis diem neque horam."}],"Offertorium":[{"k":"ref","la":"Ps 44:15-16"},{"k":"text","la":"Afferéntur Regi Vírgines post eam: próximæ ejus afferéntur tibi in lætítia et exsultatióne: adducéntur in templum Regi Dómino. (Allelúja.)"}],"Secreta":[{"k":"text","la":"Súscipe, Dómine, múnera, quæ in beátæ Catharínæ Vírginis et Mártyris tuæ sollemnitáte deférimus: cujus nos confídimus patrocínio liberári."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Ps 118:78; 118:80"},{"k":"text","la":"Confundántur supérbi, quia injúste iniquitátem fecérunt in me: ego autem in mandátis tuis exercébor, in tuis justificatiónibus, ut non confúndar. (Allelúja.)"}],"Postcommunio":[{"k":"text","la":"Auxiliéntur nobis, Dómine, sumpta mystéria: et, intercedénte beáta Catharína Vírgine et Mártyre tua, sempitérna fáciant protectióne gaudére."},{"k":"macro","name":"Per Dominum"}]},"hr":{"9a69c43b9af18214":{"t":"Ps 118, 46-47, Ps 118, 1\n(Ps 118, 46-47) Govorio sam pred kraljevima o tvojim odredbama i nisam se smeo, i razmišljao sam o tvojim zapovijedima koje veoma ljubim. (Ps 118, 1) Blago onima koji idu neokaljanim putem, koji žive po zakonu Gospodnjemu.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 118, 46-47) Govorio sam pred kraljevima o tvojim odredbama i nisam se smeo, i razmišljao sam o tvojim zapovijedima koje veoma ljubim."},"f85d8985a387013d":{"t":"<i>Pomolimo se</i>.\nBože, koji si Mojsiju dao zakon na vrhuncu gore Sinaja i na istom mjestu na čudesan način smjestio po svetim svojim anđelima tijelo blažene Katarine djevice i mučenice, daj, molimo, da po njezinim zaslugama i zagovoru zavrijedimo doći do brda, koje je Krist:\n<i>koji s Tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","v":"∅ → in"},"507bd98af25a06ac":{"t":"Sir 51, 1-8 i 12\nČitanje knjige Mudrosti. Slavim te, Gospodine Kralju, i hvalim te, Bože, Spasitelju moj. Slavim ime tvoje, jer si postao mojim pomoćnikom i zaštitnikom, spasio si me od propasti od zamke opaka jezika i od usta koja govore laži, i stao si uza me protiv mojih neprijatelja. Po svojem velikom milosrđu oslobodio si me od progonitelja, koji riču i spremni su da me prožderu. iz ruku onih koji vrebaju na me, iz muka koje me okružuju, od sile plamena koji me opkolio i nisam izgorio u ognju, iz dubine ponora, od opakog jezika i lažnih riječi, od pakosnoga poglavice i nepravednih usta. Hvalit ću te Gospodine, sve do smrti, jer ti spašavaš one koji se uzdaju u tebe, i oslobađaš ih iz bezbožničkih ruku, Gospodine naš."},"21ec89e666e72ebd":{"t":"Ps 44, 8\nLjubiš pravdu a mrziš nepravdu. Zato te je pomazao Bog, Bog tvoj, uljem radosti.\n\nPs 44, 15-16\n<i>Aleluja</i>, <i>aleluja</i>.\nZa njom će poći pred Kralja djevice, drugarice će njezine poći k tebi u radosti. <i>Aleluja</i>."},"04a5e5f3be261c56":{"t":"Mt 25, 1-13\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme reče Isus svojim učenicima: Kraljevstvo je nebesko kao deset djevica, koje uzeše svoje svjetiljke i iziđoše u susret zaručniku i zaručnici. Pet ih je bilo ludih, a pet mudrih. Pet ludih uzeše svjetiljke, a ne uzeše sa sobom ulja, a mudre sa svjetiljkama uzeše ulja u svojim posudama. Ali jer se zaručnik zabavio, sve zadrijemaše i zaspaše. A o ponoći nasta vika: Evo, ide zaručnik, iziđite mu u susret! Tada ustaše sve djevice i zapališe svoje svjetiljke. Lude tada reknu mudrima: Dajte nam od svoga ulja, jer se gase naše svjetiljke. Mudre odgovore: Da ne bi ponestalo nama i vama, idite radije do prodavača i kupite. Dok su išle kupovati, dođe zaručnik, i koje su bile spremne, uđu s njim na svadbu i zatvore se vrata. Napokon dođu i ostale djevice i reknu: Gospodine, Gospodine, otvori nam! On im odgovori: Zaista vam kažem: Ne poznam vas. Bdijte dakle, jer ne znate ni dana ni časa."},"805e908c21018a9c":{"t":"Ps 44, 15-16\nZa njom će poći pred Kralja djevice. Drugarice će njezine poći k tebi u radosti, poći će u hram Kralja Gospodina."},"397a7469238757b2":{"t":"Primi, Gospodine, darove što ti ih prinosimo na blagdan blažene Katarine djevice i mučenice tvoje, po čijem se zagovoru nadamo osloboditi.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:"},"80190e9b2b2437df":{"t":"Ps 118, 78 i 80\nNeka se postide oholi, jer me zlostavljaju bez razloga. A ja ispunjam zapovijedi tvoje i naloge tvoje da ne moram nečasno propasti."},"aed99308797fd381":{"t":"<i>Pomolimo se</i>.\nTajne koje smo primili neka nas pomažu, Gospodine, i neka po zagovoru blažene Katarine tvoje djevice i mučenice, učine da se radujemo vječnoj zaštiti.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
